{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of the packing plan — are we minimizing the number of containers used, maximizing the total weight of goods packed, or something else?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options that constitute one independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are we required to pack all available goods into containers, or is it acceptable to leave some goods unpacked?"
  ],
  "rationale": "The response contains a single clarification question asking for a policy choice between two mutually exclusive options."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Since the objective is to minimize the number of containers, are we required to pack all available goods, or is it acceptable to leave some goods unpacked?"
  ],
  "rationale": "The response contains a single clarification question asking for a policy choice regarding whether all goods must be packed or if some can be left unpacked."
}

